contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public entry that will be called once by checker
    // We pick a variety of inputs to call several logging functions
    function run(address caller, address keepAddress, bytes32 digest, bytes32 r, bytes32 s, bytes32 pubx, bytes32 puby, bytes32 txid, uint256 utxoSize, bytes memory redeemerOutputScript, uint256 requestedFee, bytes memory outpoint, bool wasFraud) public payable {
        require(caller != address(0));
        // Record approval status for this contract (msg.sender will be this test contract when it calls c).
        bool beforeSelf = c.approvedToLog(address(this)); if (__ESBMC_reverted()) return;
        // Also record approval for the arbitrary 'caller' parameter to observe unchanged behavior
        bool beforeOther = c.approvedToLog(caller); if (__ESBMC_reverted()) return;

        // Make a series of logging calls that may return false or true depending on approval.
        bool ok1 = c.logCreated(keepAddress); if (__ESBMC_reverted()) return;
        bool ok2 = c.logRedemptionRequested(address(this), digest, utxoSize, redeemerOutputScript, requestedFee, outpoint); if (__ESBMC_reverted()) return;
        bool ok3 = c.logGotRedemptionSignature(digest, r, s); if (__ESBMC_reverted()) return;
        bool ok4 = c.logRegisteredPubkey(pubx, puby); if (__ESBMC_reverted()) return;
        bool ok5 = c.logSetupFailed(); if (__ESBMC_reverted()) return;
        bool ok6 = c.logFraudDuringSetup(); if (__ESBMC_reverted()) return;
        bool ok7 = c.logFunded(); if (__ESBMC_reverted()) return;
        bool ok8 = c.logCourtesyCalled(); if (__ESBMC_reverted()) return;
        bool ok9 = c.logStartedLiquidation(wasFraud); if (__ESBMC_reverted()) return;
        bool ok10 = c.logRedeemed(txid); if (__ESBMC_reverted()) return;
        bool ok11 = c.logLiquidated(); if (__ESBMC_reverted()) return;
        bool ok12 = c.logExitedCourtesyCall(); if (__ESBMC_reverted()) return;

        // Read approvals after calling logging functions
        bool afterSelf = c.approvedToLog(address(this)); if (__ESBMC_reverted()) return;
        bool afterOther = c.approvedToLog(caller); if (__ESBMC_reverted()) return;

        // General rule: none of the logging calls should ever change approval mappings.
        // Therefore approvals for this contract and for 'caller' must be unchanged.
        // Additionally, each returned bool is consistent with whether the caller was approved at the time:
        // If beforeSelf was true then all ok* should be true; if beforeSelf was false then all ok* should be false.
        // We assert that the approval bits remain identical and that all okX equal beforeSelf.
        assert(
            afterSelf == beforeSelf
            && afterOther == beforeOther
            && ok1 == beforeSelf
            && ok2 == beforeSelf
            && ok3 == beforeSelf
            && ok4 == beforeSelf
            && ok5 == beforeSelf
            && ok6 == beforeSelf
            && ok7 == beforeSelf
            && ok8 == beforeSelf
            && ok9 == beforeSelf
            && ok10 == beforeSelf
            && ok11 == beforeSelf
            && ok12 == beforeSelf
        );
    }

    receive() external payable {}
}

